  import SvgFlow from './svgflow.vue';
import History from './history'

  export default {
      name: 'FlowFile',
      components: {
          SvgFlow,History
      },
      props: {
        showHistory:{type:Boolean,default:true },
          noHover: {type: Boolean, default: false,},
          processInsId: {type: String, default: ''},
          businessId: {type: String, default: ''},
          processKey: {type: String, default: ''}
      },
      data() {
          return {
              show: false,
            activeName:'first'
          };
      },
      watch: {
          processInsId() {
           // console.log(this.processInsId +' ===' + this.processKey + "---" +this.businessId)
              this.show = !this.show;
          }
      },
      methods: {
           showCallTable() {
              this.$emit('showCallTable')
          },
          filterTableData() {
              this.$emit('filterTableData')
          },
           getFowFile() {
              this.$emit('getFowFile')
          },
          close() {
              this.$emit('close')
          }
      }
  };
